using sv_2d1f2891c6bf44eab0136b114c209ce9.Models;

namespace sv_2d1f2891c6bf44eab0136b114c209ce9.Services;

public interface IRecipeService
{
    Task<List<Recipe>> GetByCuisineAsync(int cuisineId, CancellationToken cancellationToken);
}

using sv_2d1f2891c6bf44eab0136b114c209ce9.Models;

namespace sv_2d1f2891c6bf44eab0136b114c209ce9.Services;

public sealed class RecipeService : IRecipeService
{
    private static readonly Dictionary<int, List<Recipe>> SeedData = new()
    {
        [1] = new List<Recipe>
        {
            new(1, "Margherita Pizza", "Classic Neapolitan pizza with tomato, mozzarella, and basil.", 30),
            new(2, "Pasta Carbonara", "Creamy Roman pasta with egg, pecorino, guanciale, and black pepper.", 25),
            new(3, "Tiramisu", "Layered coffee-flavored Italian dessert with mascarpone cream.", 45),
        },
        [2] = new List<Recipe>
        {
            new(4, "Sushi Rolls", "Vinegared rice with fresh fish and vegetables wrapped in nori.", 60),
            new(5, "Ramen", "Rich pork-bone broth with wheat noodles, chashu, and soft-boiled egg.", 90),
            new(6, "Tempura", "Lightly battered and deep-fried shrimp and seasonal vegetables.", 35),
        },
        [3] = new List<Recipe>
        {
            new(7, "Tacos al Pastor", "Marinated pork tacos with pineapple, cilantro, and onion.", 40),
            new(8, "Guacamole", "Fresh avocado dip with lime, cilantro, jalapeño, and tomato.", 15),
            new(9, "Churros", "Fried dough pastry coated in cinnamon sugar, served with chocolate.", 50),
        },
    };

    public async Task<List<Recipe>> GetByCuisineAsync(int cuisineId, CancellationToken cancellationToken)
    {
        await Task.Delay(2000, cancellationToken);

        if (SeedData.TryGetValue(cuisineId, out var recipes))
        {
            return recipes;
        }

        return new List<Recipe>();
    }
}

@page "/recipes/{CuisineId:int}"
@rendermode InteractiveServer
@implements IDisposable
@using sv_2d1f2891c6bf44eab0136b114c209ce9.Models
@using sv_2d1f2891c6bf44eab0136b114c209ce9.Services
@inject IRecipeService RecipeService
@inject NavigationManager Navigation
@inject ILogger<Recipes> Logger

<PageTitle>Recipes</PageTitle>

<h1>Recipes — Cuisine @CuisineId</h1>

@if (_errorMessage is not null)
{
    <div class="alert alert-danger" role="alert">
        <p>@_errorMessage</p>
        <button class="btn btn-outline-danger btn-sm" @onclick="RetryAsync">Retry</button>
    </div>
}
else if (_recipes is null)
{
    <p><em>Loading recipes…</em></p>
}
else
{
    @if (_isRefreshing)
    {
        <div class="alert alert-info py-1 px-2 d-inline-block" role="status">Refreshing…</div>
    }

    <div>
        <label class="me-2">Sort:</label>
        <a href="@GetSortUrl("newest")" class="btn btn-sm @(_sort == "newest" ? "btn-primary" : "btn-outline-primary") me-1">Newest</a>
        <a href="@GetSortUrl("popular")" class="btn btn-sm @(_sort == "popular" ? "btn-primary" : "btn-outline-primary")">Popular</a>
    </div>

    @if (_recipes.Count == 0)
    {
        <p class="mt-3">No recipes found for this cuisine.</p>
    }
    else
    {
        <table class="table mt-3">
            <thead>
                <tr>
                    <th>Title</th>
                    <th>Description</th>
                    <th>Prep Time (min)</th>
                </tr>
            </thead>
            <tbody>
                @foreach (var recipe in GetSortedRecipes())
                {
                    <tr>
                        <td>@recipe.Title</td>
                        <td>@recipe.Description</td>
                        <td>@recipe.PrepTimeMinutes</td>
                    </tr>
                }
            </tbody>
        </table>
    }
}

@code {
    [Parameter]
    public int CuisineId { get; set; }

    [SupplyParameterFromQuery(Name = "sort")]
    public string? Sort { get; set; }

    private List<Recipe>? _recipes;
    private string? _errorMessage;
    private bool _isRefreshing;
    private string _sort = "newest";
    private int _loadedCuisineId;

    private CancellationTokenSource? _loadCts;
    private readonly CancellationTokenSource _disposeCts = new();

    protected override async Task OnParametersSetAsync()
    {
        _sort = string.Equals(Sort, "popular", StringComparison.OrdinalIgnoreCase) ? "popular" : "newest";

        if (CuisineId == _loadedCuisineId && _recipes is not null)
        {
            // Only sort changed — no reload needed.
            return;
        }

        await LoadRecipesAsync();
    }

    private async Task LoadRecipesAsync()
    {
        // Cancel any in-flight load for the previous cuisine.
        if (_loadCts is not null)
        {
            await _loadCts.CancelAsync();
            _loadCts.Dispose();
        }

        _loadCts = CancellationTokenSource.CreateLinkedTokenSource(_disposeCts.Token);

        _errorMessage = null;
        _isRefreshing = _recipes is not null;

        var cuisineId = CuisineId;
        var token = _loadCts.Token;

        try
        {
            var results = await RecipeService.GetByCuisineAsync(cuisineId, token);

            // Guard against a stale callback after cancellation.
            if (token.IsCancellationRequested)
            {
                return;
            }

            _recipes = results;
            _loadedCuisineId = cuisineId;
        }
        catch (OperationCanceledException) when (token.IsCancellationRequested)
        {
            // Expected — the user navigated away or switched cuisine.
        }
        catch (TimeoutException ex)
        {
            Logger.LogError(ex, "Timeout loading recipes for cuisine {CuisineId}", cuisineId);
            _errorMessage = "The request timed out. Please try again.";
        }
        catch (Exception ex) when (ex is not OperationCanceledException)
        {
            Logger.LogError(ex, "Error loading recipes for cuisine {CuisineId}", cuisineId);
            _errorMessage = "Something went wrong while loading recipes. Please try again.";
        }
        finally
        {
            _isRefreshing = false;
        }
    }

    private async Task RetryAsync()
    {
        await LoadRecipesAsync();
    }

    private IEnumerable<Recipe> GetSortedRecipes()
    {
        if (_recipes is null)
        {
            return Enumerable.Empty<Recipe>();
        }

        return _sort == "popular"
            ? _recipes.OrderBy(r => r.PrepTimeMinutes)
            : _recipes.OrderByDescending(r => r.Id);
    }

    private string GetSortUrl(string sortValue)
    {
        return Navigation.GetUriWithQueryParameter("sort", sortValue);
    }

    public void Dispose()
    {
        _disposeCts.Cancel();
        _disposeCts.Dispose();
        _loadCts?.Dispose();
    }
}

