+    private readonly CancellationTokenSource _disposeCts = new();
+
+    protected override async Task OnParametersSetAsync()
+    {
+        _sort = string.Equals(Sort, "popular", StringComparison.OrdinalIgnoreCase) ? "popular" : "newest";
+
+        if (CuisineId == _loadedCuisineId && _recipes is not null)
+        {
+            // Only sort changed — no reload needed.
+            return;
+        }
+
+        await LoadRecipesAsync();
+    }
+
+    private async Task LoadRecipesAsync()
+    {
+        // Cancel any in-flight load for the previous cuisine.
+        if (_loadCts is not null)
+        {
+            await _loadCts.CancelAsync();
+            _loadCts.Dispose();
+        }
+
+        _loadCts = CancellationTokenSource.CreateLinkedTokenSource(_disposeCts.Token);
+
+        _errorMessage = null;
+        _isRefreshing = _recipes is not null;
+
+        var cuisineId = CuisineId;
+        var token = _loadCts.Token;
+
+        try
+        {
+            var results = await RecipeService.GetByCuisineAsync(cuisineId, token);
+
+            // Guard against a stale callback after cancellation.
+            if (token.IsCancellationRequested)
+            {
+                return;
+            }
+
+            _recipes = results;
+            _loadedCuisineId = cuisineId;
+        }
+        catch (OperationCanceledException) when (token.IsCancellationRequested)
+        {
+            // Expected — the user navigated away or switched cuisine.
+        }
+        catch (TimeoutException ex)
+        {
+            Logger.LogError(ex, "Timeout loading recipes for cuisine {CuisineId}", cuisineId);
+            _errorMessage = "The request timed out. Please try again.";
+        }
+        catch (Exception ex) when (ex is not OperationCanceledException)
+        {
+            Logger.LogError(ex, "Error loading recipes for cuisine {CuisineId}", cuisineId);
+            _errorMessage = "Something went wrong while loading recipes. Please try again.";
+        }
+        finally
+        {
+            _isRefreshing = false;
+        }
+    }
+
+    private async Task RetryAsync()
+    {
+        await LoadRecipesAsync();
+    }
+
+    private IEnumerable<Recipe> GetSortedRecipes()
+    {
+        if (_recipes is null)
+        {
+            return Enumerable.Empty<Recipe>();
+        }
+
+        return _sort == "popular"
+            ? _recipes.OrderBy(r => r.PrepTimeMinutes)
+            : _recipes.OrderByDescending(r => r.Id);
+    }
+
+    private string GetSortUrl(string sortValue)
+    {
+        return Navigation.GetUriWithQueryParameter("sort", sortValue);
+    }
+
+    public void Dispose()
+    {
+        _disposeCts.Cancel();
+        _disposeCts.Dispose();
+        _loadCts?.Dispose();
+    }
+}
